        if (fieldSet != null) {
            for (Schema.DescribeFieldSetResult.SObjectFieldInfo fieldInfo : fieldSet.getDisplayedFields()) {
                Schema.SObjectField field = fieldInfo.getDescribeField();
                if (!fields.contains(field)) {
                    fields.add(field);
                }
            }
        }

        return fields;
    }

    protected fflib_SObjectDataAccess createDataAccess() {
        return new UserModeDataAccess();
    }

